            "type": "boolean",
            "description": "If true, discards uncommitted local changes and overwrites working tree during pull. Defaults to false."
          }
        },
        "required": []
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "create_dir",
      "description": "Creates a directory at the specified path, including any necessary parent directories. Returns a success confirmation or an error if the path exists as a file.",
      "parameters": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Absolute or relative filesystem path for the new directory. Parent directories will be created if missing."
          }
        },
        "required": [
          "path"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "git_star",
      "description": "Stars a GitHub repository identified by the owner and repository name. If owner is not provided, defaults to the current authenticated user. Returns a success status upon completion.",
      "parameters": {
        "type": "object",
        "properties": {
          "repo_name": {
            "type": "string",
            "description": "The name of the repository (without the owner)."
          },
          "owner": {
            "type": "string",
            "description": "Owner of the repository (username or organization). If omitted, the current authenticated user is used."
          }
        },
        "required": [
          "repo_name"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "move_node",
      "description": "Moves or renames a local file or directory within the GitHub repository context from the source path to the destination path. Returns the absolute path of the moved node.",
      "parameters": {
        "type": "object",
        "properties": {
          "source_path": {
            "type": "string",
            "description": "The current absolute or relative path of the node (file or directory) to be moved or renamed."
          },
          "destination_path": {
            "type": "string",
            "description": "The target absolute or relative path for the node, which may include a new name or directory location."
          }
        },
        "required": [
          "source_path",
          "destination_path"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "git_transfer_repo_ownership",
      "description": "Transfers ownership of a specified repository to a new owner identified by GitHub username or email. Returns success status and transferred repository details.",
      "parameters": {
        "type": "object",
        "properties": {
          "repo_name": {
            "type": "string",
            "description": "The full name of the repository to transfer (e.g., 'current_user/repo')"
          },
          "new_owner_username": {
            "type": "string",
            "description": "GitHub username of the recipient account. Required if new_owner_email is not provided."
          },
          "new_owner_email": {
            "type": "string",
            "description": "Email address of the recipient account. Required if new_owner_username is not provided."
          }
        },
        "required": [
          "repo_name"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "input_to_webpage",
      "description": "Fills and submits a web form on the specified URL by providing values for input fields identified by their IDs or names. Returns the HTML content of the resulting page or an error message.",
      "parameters": {
        "type": "object",
        "properties": {
          "url": {
            "type": "string",
            "description": "Absolute URL of the webpage containing the target form."
          },
          "inputs": {
            "type": "object",
            "description": "Mapping of HTML input element identifiers (IDs or names) to values for form filling. Example: {'username': 'test_user', 'password': 'secure123'}."
          }
        },
        "required": [
          "url",
          "inputs"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "git_delete_repo",
      "description": "Permanently deletes the specified GitHub repository after verifying OTP. Returns a success confirmation message upon deletion.",
      "parameters": {
        "type": "object",
        "properties": {
          "repo_name": {
            "type": "string",
            "description": "Name of the repository to delete"
          }
        },
        "required": [
          "repo_name"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "git_add_ssh_key",
      "description": "Adds an SSH public key to the current GitHub account, requiring two-factor authentication via OTP. Returns a success confirmation message including the key ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "ssh_key": {
            "type": "string",
            "description": "The public SSH key to add, in OpenSSH format (e.g., 'ssh-rsa AAAA...')"
          }
        },
        "required": [
          "ssh_key"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "download_file_through_id",
      "description": "Downloads an email attachment to a local directory using its attachment ID and returns the absolute path of the saved file. Default save directory is '/downloads'.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_id": {
            "type": "string",
            "description": "The unique identifier of the email attachment to download."
          },
          "save_dir": {
            "type": "string",
            "description": "Absolute path of the directory to save the file. Defaults to '/downloads' if omitted."
          }
        },
        "required": [
          "file_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "browse_webpage",
      "description": "Visits the specified URL to retrieve its web content or simulate clicking a link that triggers an action. Returns the page content as a string.",
      "parameters": {
        "type": "object",
        "properties": {
          "url": {
            "type": "string",
            "description": "The absolute URL to visit, which must include the protocol (e.g., 'https://')"
          }
        },
        "required": [
          "url"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "copy_node",
      "description": "Copies a local file or directory within the GitHub environment from the source path to the destination path. Returns the absolute path of the copied file/directory on success.",
      "parameters": {
        "type": "object",
        "properties": {
          "source_path": {
            "type": "string",
            "description": "Absolute or relative path of the file/directory to copy. Relative paths resolve from the current working directory."
          },
          "destination_path": {
            "type": "string",
            "description": "Destination path where the copy will be placed. If a directory, source is copied inside it; otherwise, it's treated as a new full path."
          }
        },
        "required": [
          "source_path",
          "destination_path"
        ]
      }
    }
  }
]

