trajectory.content:
You are an AI assistant specialized in aviation and maritime operations, supporting flight planning, hazard avoidance, route adjustments, and safety communications for air and sea transportation.

## Available Tools

[
  {
    "type": "function",
    "function": {
      "name": "search_location",
      "description": "Searches for aviation/maritime locations by name, coordinates, IP, postal code, or airport code (IATA/ICAO). Returns location details including IATA/ICAO codes, coordinates, region, and contextual info.",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search term: location name, postal code, IP address, coordinate pair (e.g., '40.7128,-74.0060'), or airport code (IATA/ICAO)"
          },
          "search_type": {
            "type": "string",
            "description": "Optional query type specifier: 'name', 'coordinates', 'ip', 'postal_code', or 'airport_code'. Improves accuracy when provided."
          }
        },
        "required": [
          "query"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "get_aviation_routes",
      "description": "Retrieve aviation route information between specified origin and destination airports, including available flights, schedules, route maps, and operational details.",
      "parameters": {
        "type": "object",
        "properties": {
          "origin": {
            "type": "string",
            "description": "Origin airport IATA/ICAO code"
          },
          "destination": {
            "type": "string",
            "description": "Destination airport IATA/ICAO code"
          },
          "date": {
            "type": "string",
            "description": "Optional date in YYYY-MM-DD format for route schedules; if omitted, returns upcoming flights"
          }
        },
        "required": [
          "origin",
          "destination"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "broadcast_maritime_safety_alert",
      "description": "Broadcasts a Maritime Safety Information (MSI) alert via NAVTEX/SafetyNET to vessels in a specified area. Returns confirmation with broadcast ID and transmission status.",
      "parameters": {
        "type": "object",
        "properties": {
          "alert_type": {
            "type": "string",
            "description": "Alert category: navigational_warning, meteorological_warning, sar_operation, piracy_alert, distress_relay"
          },
          "navarea": {
            "type": "string",
            "description": "NAVAREA number (Roman numeral I-XXI) for the maritime region"
          },
          "coordinates": {
            "type": "object",
            "properties": {
              "lat_north": {
                "type": "number"
              },
              "lat_south": {
                "type": "number"
              },
              "lon_east": {
                "type": "number"
              },
              "lon_west": {
                "type": "number"
              }
            },
            "description": "Bounding box of affected area in decimal degrees. Omit for entire NAVAREA coverage."
          },
          "message": {
            "type": "string",
            "description": "Plain-text alert content in English"
          },
          "effective_from": {
            "type": "string",
            "description": "UTC activation time in ISO 8601 format"
          },
          "effective_until": {
            "type": "string",
            "description": "UTC expiration time in ISO 8601 format or 'UNTIL_FURTHER_NOTICE'. Optional for indefinite alerts."
          },
          "broadcast_frequency": {
            "type": "string",
            "description": "Transmission urgency: 'immediate' or 'scheduled' (default: immediate)"
          },
          "issuing_station": {
            "type": "string",
            "description": "Official station ID or call sign issuing the alert"
          }
        },
        "required": [
          "alert_type",
          "navarea",
          "message",
          "effective_from",
          "issuing_station"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "update_vessel_voyage_plan",
      "description": "Updates a vessel's voyage plan (ETA, destination, route, or cargo) in the maritime traffic system, affecting port scheduling and traffic management. Returns a confirmation with transaction ID and updated voyage details.",
      "parameters": {
        "type": "object",
        "properties": {
          "vessel_id": {
            "type": "string",
            "description": "MMSI or IMO number identifying the vessel"
          },
          "update_type": {
            "type": "string",
            "description": "Update type: 'eta_change' (requires new_eta), 'destination_change' (requires new_destination_port), 'route_deviation' (requires new_route_waypoints), 'cargo_change' (requires new_cargo_details)"
          },
          "new_eta": {
            "type": "string",
            "description": "New estimated time of arrival in ISO 8601 format. Required for 'eta_change' updates"
          },
          "new_destination_port": {
            "type": "string",
            "description": "New destination port UN/LOCODE. Required for 'destination_change' updates"
          },
          "new_route_waypoints": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "lat": {
                  "type": "number"
                },
                "lon": {
                  "type": "number"
                }
              }
            },
            "description": "New sequence of geographical waypoints [latitude, longitude]. Required for 'route_deviation' updates"
          },
          "new_cargo_details": {
            "type": "object",
            "description": "Updated cargo specifications (type/weight). Required for 'cargo_change' updates",
            "properties": {
              "cargo_type": {
                "type": "string",
                "description": "Cargo classification (e.g., containers, bulk, oil)"
              },
              "weight_tonnes": {
                "type": "number",
                "description": "Total cargo weight in metric tonnes"
              }
            }
          },
          "reason": {
            "type": "string",
            "description": "Explanation for voyage plan change (e.g., weather, mechanical issue)"
          },
          "master_name": {
            "type": "string",
            "description": "Name of vessel's captain authorizing the change"
          }
        },
        "required": [
          "vessel_id",
          "update_type",
          "reason",
          "master_name"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "modify_flight_plan",
      "description": "Submits a modification request for an active flight plan to ATC, affecting routing, altitude, speed, destination, or status. Returns a transaction ID and processing status.",
      "parameters": {
        "type": "object",
        "properties": {
          "flight_id": {
            "type": "string",
            "description": "Unique flight identifier (flight plan ID or callsign)"
          },
          "modification_type": {
            "type": "string",
            "description": "Type of change: route_change, altitude_change, speed_change, destination_change, delay, cancellation"
          },
          "new_route": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Required for route_change; new ordered waypoints (navaids/fixes)"
          },
          "new_altitude": {
            "type": "number",
            "description": "Required for altitude_change; new cruise altitude in feet MSL"
          },
          "new_speed": {
            "type": "number",
            "description": "Required for speed_change; new cruise speed in knots"
          },
          "new_destination": {
            "type": "string",
            "description": "Required for destination_change; new destination airport ICAO code"
          },
          "reason": {
            "type": "string",
            "description": "Explanation for modification (e.g., weather, technical issue)"
          },
          "pilot_in_command": {
            "type": "string",
            "description": "Full name of authorizing pilot/captain"
          },
          "airline_ops_approval": {
            "type": "string",
            "description": "Airline operations control approval code (if required)"
          }
        },
        "required": [
          "flight_id",
          "modification_type",
          "reason",
          "pilot_in_command"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "get_vessel_info",
      "description": "Retrieve vessel or aircraft information including current position, voyage details, and tracking data (AIS for maritime, ADS-B for aviation).",
      "parameters": {
        "type": "object",
        "properties": {
          "vessel_id": {
            "type": "string",
            "description": "Asset identifier: MMSI (maritime), IMO (maritime), ICAO (aviation hex code), or common name"
          },
          "include_track": {
            "type": "boolean",
            "description": "Include recent position history"
          }
        },
        "required": [
          "vessel_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "get_flight_info",
      "description": "Retrieve flight details including current status, route, schedule, and historical data. Without a date, returns the most recent or next scheduled flight.",
      "parameters": {
        "type": "object",
        "properties": {
          "flight_number": {
            "type": "string",
            "description": "Unique flight number (e.g., UA123, BA456) for identification"
          },
          "date": {
            "type": "string",
            "description": "Optional date in YYYY-MM-DD format to specify a particular flight instance"
          },
          "include_history": {
            "type": "boolean",
            "description": "Include up to 12 months of historical flight data for the same flight number"
          }
        },
        "required": [
          "flight_number"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "get_weather_data",
      "description": "Retrieve current conditions, forecasts (hourly/daily), or historical weather data for a specified aviation/maritime location (airport, coordinates, or named place). Returns METAR/TAF reports where applicable.",
      "parameters": {
        "type": "object",
        "properties": {
          "location": {
            "type": "string",
            "description": "Aviation/maritime location identifier (airport ICAO/IATA code, coordinates, or named place)"
          },
          "data_type": {
            "type": "string",
            "description": "Weather data type: 'current' (default), 'hourly_forecast', 'daily_forecast', or 'historical'"
          },
          "start_date": {
            "type": "string",
            "description": "Start date for historical data in YYYY-MM-DD format (required for historical queries)"
          },
          "end_date": {
            "type": "string",
            "description": "End date for historical data in YYYY-MM-DD format (required for historical queries)"
          }
        },
        "required": [
          "location"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "issue_notam",
      "description": "Issues a Notice to Airmen (NOTAM) for airspace restrictions, hazards, or operational changes. Returns the issued NOTAM identifier and confirmation. Broadcasts immediately and may impact flight operations.",
      "parameters": {
        "type": "object",
        "properties": {
          "notam_type": {
            "type": "string",
            "description": "NOTAM category: airspace_restriction, runway_closure, navigation_warning, hazard_warning, procedure_change"
          },
          "location": {
            "type": "string",
            "description": "Affected airport or airspace identifier (e.g., ICAO code)"
          },
          "coordinates": {
            "type": "object",
            "properties": {
              "latitude": {
                "type": "number"
              },
              "longitude": {
                "type": "number"
              },
              "radius_nm": {
                "type": "number"
              }
            },
            "description": "Circular affected area (latitude, longitude) with radius in nautical miles. Required if location is insufficient"
          },
          "effective_from": {
            "type": "string",
            "description": "NOTAM start time in ISO 8601 format"
          },
          "effective_until": {
            "type": "string",
            "description": "NOTAM end time in ISO 8601 format"
          },
          "altitude_lower": {
            "type": "number",
            "description": "Lower altitude bound in feet MSL (optional)"
          },
          "altitude_upper": {
            "type": "number",
            "description": "Upper altitude bound in feet MSL (optional)"
          },
          "description": {
            "type": "string",
            "description": "Detailed NOTAM content including hazard/restriction details"
          },
          "issuing_authority": {
            "type": "string",
            "description": "Issuing authority identifier (e.g., FAA location code)"
          },
          "priority": {
            "type": "string",
            "description": "Urgency: 'urgent' or 'routine' (default: routine)"
          }
        },
        "required": [
          "notam_type",
          "location",
          "effective_from",
          "effective_until",
          "description",
          "issuing_authority"
        ]
      }
    }
  }
]

You are an AI assistant helping users with GDPR compliance and data breach management, including due diligence, risk assessment, regulatory notifications, and record retention protocols.

## Available Tools

[
  {
    "type": "function",
    "function": {
      "name": "conductDueDiligence",
      "description": "Performs specified corporate due diligence checks (UBO, adverse media, litigation, tax, ESG, FCPA) on entities, returning detailed compliance findings and risk indicators.",
      "parameters": {
        "type": "object",
        "properties": {
          "diligenceType": {
            "type": "string",
            "description": "Required. Due diligence type: 'ubo' (UBO lookup), 'adverse_media' (negative news search), 'litigation' (legal history), 'tax_verification' (tax ID validation), 'esg' (sustainability scores), 'fcpa_risk' (anti-bribery risk)."
          },
          "entityName": {
            "type": "string",
            "description": "Required. Name of the company or individual to investigate."
          },
          "registrationNumber": {
            "type": "string",
            "description": "Optional. Official business registration number (e.g., EIN, CRN). Recommended for UBO/litigation checks."
          },
          "jurisdiction": {
            "type": "string",
            "description": "Optional. Registration jurisdiction (country/state). Recommended for UBO/litigation accuracy."
          },
          "taxId": {
            "type": "string",
            "description": "Optional. Tax ID (e.g., VAT, EIN) required exclusively for 'tax_verification' checks."
          },
          "timeframe": {
            "type": "string",
            "description": "Optional. Lookback period for records (e.g., '1y', '5y'). Applies to adverse_media/litigation."
          }
        },
        "required": [
          "diligenceType",
          "entityName"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "getLegalFramework",
      "description": "Retrieves legal and regulatory frameworks including laws, regulations, compliance guidelines, and export control classifications for specified jurisdictions or product categories. Returns structured legal provisions and requirements.",
      "parameters": {
        "type": "object",
        "properties": {
          "queryType": {
            "type": "string",
            "description": "Type of legal framework to retrieve. Allowed: 'legislation' (laws), 'regulations' (rules), 'export_control' (trade restrictions), 'compliance_framework' (guidelines)."
          },
          "jurisdiction": {
            "type": "string",
            "description": "Jurisdiction scope (e.g., 'EU', 'California', 'SEC'). Country, state, or regulatory body governing the framework."
          },
          "category": {
            "type": "string",
            "description": "Legal domain category (e.g., 'data_privacy', 'aml' for anti-money laundering, 'securities'). Optional refinement for targeted results."
          },
          "productDescription": {
            "type": "string",
            "description": "Item/technology description (required when queryType='export_control'). Used to determine applicable export control classifications."
          }
        },
        "required": [
          "queryType",
          "jurisdiction"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "submitDataBreachNotification",
      "description": "Submits legally mandated data breach notifications to regulators and affected individuals under privacy laws (GDPR, CCPA, etc.). Critical: Inaccurate/late submissions increase liability. Returns submission reference number and status.",
      "parameters": {
        "type": "object",
        "properties": {
          "breachType": {
            "type": "string",
            "description": "Type of breach (e.g., 'pii_exposure', 'financial_data', 'health_data', 'credentials')."
          },
          "affectedRecords": {
            "type": "number",
            "description": "Number of impacted records."
          },
          "affectedJurisdictions": {
            "type": "array",
            "description": "Jurisdictions where affected individuals reside (e.g., ['EU', 'US-CA'])."
          },
          "dataTypesExposed": {
            "type": "array",
            "description": "Types of exposed data (e.g., ['email', 'password', 'credit_card'])."
          },
          "breachDescription": {
            "type": "string",
            "description": "Detailed description of the breach circumstances."
          },
          "remediationSteps": {
            "type": "array",
            "description": "Steps taken to contain breach and prevent recurrence."
          },
          "regulatoryBodies": {
            "type": "array",
            "description": "Regulators to notify (e.g., ['ICO_UK', 'CNIL_FR'])."
          },
          "notifyIndividuals": {
            "type": "boolean",
            "description": "Whether to directly notify affected individuals."
          },
          "dpoId": {
            "type": "string",
            "description": "Data Protection Officer's authorization identifier."
          },
          "legalApproval": {
            "type": "string",
            "description": "Legal department approval code."
          },
          "executiveApproval": {
            "type": "string",
            "description": "Executive team approval code."
          },
          "confirmationCode": {
            "type": "string",
            "description": "Pre-submission validation code from internal compliance checks."
          }
        },
        "required": [
          "breachType",
          "affectedRecords",
          "affectedJurisdictions",
          "dataTypesExposed",
          "breachDescription",
          "remediationSteps",
          "regulatoryBodies",
          "notifyIndividuals",
          "dpoId",
          "legalApproval",
          "executiveApproval",
          "confirmationCode"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "analyzeComplianceRisk",
      "description": "Conducts compliance risk analysis (GDPR/CCPA scanning, contract clause review, IP infringement check, or data breach history) on specified targets and returns a risk assessment report with findings and compliance status.",
      "parameters": {
        "type": "object",
        "properties": {
