    "type": "function",
    "function": {
      "name": "getOperationalMetrics",
      "description": "Retrieves operational metrics for public transit systems including performance, traffic conditions, weather impacts, and service reliability. Returns aggregated data for the entire network or specific transit lines over a specified historical period.",
      "parameters": {
        "type": "object",
        "properties": {
          "metricType": {
            "type": "string",
            "description": "Required. Metric category: 'performance' (on-time rates, delays), 'traffic' (congestion levels), 'weather' (service alerts/impacts), or 'reliability' (service consistency indices)."
          },
          "lineId": {
            "type": "string",
            "description": "Optional. Transit line ID (bus/rail) to scope metrics. Omit for network-wide data."
          },
          "timeframeDays": {
            "type": "number",
            "description": "Optional. Historical data duration in days (e.g., 7 for last week). Defaults to system-defined period if omitted."
          }
        },
        "required": [
          "metricType"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "suspendTransitLine",
      "description": "Suspends transit service on specified lines/routes due to critical incidents. Returns a confirmation record with suspension details, impact assessment, and the assigned confirmation code.",
      "parameters": {
        "type": "object",
        "properties": {
          "lineIds": {
            "type": "array",
            "description": "Identifiers of transit lines to suspend. Must reference active lines."
          },
          "suspensionType": {
            "type": "string",
            "description": "Scope of suspension: 'partial' (segment), 'full' (entire line), or 'indefinite' (unknown duration)."
          },
          "reason": {
            "type": "string",
            "description": "Cause for suspension. Valid: 'safety_incident', 'weather', 'infrastructure_failure', 'security_threat'."
          },
          "alternativeService": {
            "type": "string",
            "description": "Contingency transit arrangements for affected passengers (e.g., shuttle routes, partner services)."
          },
          "dispatcherId": {
            "type": "string",
            "description": "Unique identifier of the authorized dispatcher initiating the suspension."
          },
          "supervisorApproval": {
            "type": "string",
            "description": "Verification code from supervisory authorization for this action."
          },
          "confirmationCode": {
            "type": "string",
            "description": "Unique tracking code for the suspension event, used in audits and passenger communications."
          }
        },
        "required": [
          "lineIds",
          "suspensionType",
          "reason",
          "alternativeService",
          "dispatcherId",
          "supervisorApproval",
          "confirmationCode"
        ]
      }
    }
  },
  {
    "type": "function",
