          },
          "priority": {
            "type": "string",
            "description": "Required. Urgency level: 'low', 'medium', 'high', or 'emergency'."
          },
          "problemSummary": {
            "type": "string",
            "description": "Required. Concise description of the issue, including symptoms and operational impact."
          }
        },
        "required": [
          "assetId",
          "assetType",
          "priority",
          "problemSummary"
        ]
      }
    }
  },
